<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Auto‑Pilot Cave Scroller</title>
<style>
  body,html{margin:0;padding:0;overflow:hidden;background:#000;color:#fff;font-family:sans-serif;}
  #dist{position:absolute;top:10px;left:10px;font-size:20px;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="dist">0 m</div>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  let W = canvas.width = window.innerWidth;
  let H = canvas.height = window.innerHeight;

  const GAP = 150;          // vertical gap between ceiling & floor
  const SPEED = 2;          // scrolling speed (px per frame)
  const LOOK = 150;         // look‑ahead distance for the AI
  const SHIP_X = 100;       // fixed horizontal position of the ship

  let offset = 0;           // horizontal offset for the cave generation
  let distance = 0;         // travelled distance in meters

  const ship = {y: H/2, vy: 0};

  // Resize handling
  window.addEventListener('resize', () => {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
  });

  // Helper: compute centre line at a world‑x coordinate
  const centreAt = x => H/2 + Math.sin((x+offset)*0.02)*80;

  function drawCave() {
    // background
    ctx.fillStyle = '#111';
    ctx.fillRect(0,0,W,H);

    // ceiling
    ctx.fillStyle = '#444';
    ctx.beginPath();
    ctx.moveTo(0,0);
    for (let x=0;x<=W;x++) {
      const c = centreAt(x);
      const ceil = c - GAP/2;
      ctx.lineTo(x, ceil);
    }
    ctx.lineTo(W,0);
    ctx.closePath();
    ctx.fill();

    // floor
    ctx.beginPath();
    ctx.moveTo(0,H);
    for (let x=0;x<=W;x++) {
      const c = centreAt(x);
      const floor = c + GAP/2;
      ctx.lineTo(x, floor);
    }
    ctx.lineTo(W,H);
    ctx.closePath();
    ctx.fill();
  }

  function drawShip() {
    const size = 12;
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(SHIP_X, ship.y);
    ctx.lineTo(SHIP_X - size, ship.y + size);
    ctx.lineTo(SHIP_X - size, ship.y - size);
    ctx.closePath();
    ctx.fill();
  }

  function updateShip() {
    // Look ahead to the centre of the upcoming gap
    const targetX = SHIP_X + LOOK;
    const targetCentre = centreAt(targetX);
    const error = targetCentre - ship.y;

    // Simple proportional controller
    ship.vy += error * 0.001;
    // Damping
    ship.vy *= 0.98;

    ship.y += ship.vy;

    // Keep ship within screen (optional safety)
    if (ship.y < 0) ship.y = 0;
    if (ship.y > H) ship.y = H;
  }

  function loop() {
    offset += SPEED;
    distance += SPEED * 0.1; // assume 0.1 m per pixel for demo
    document.getElementById('dist').textContent = `${Math.floor(distance)} m`;

    drawCave();
    updateShip();
    drawShip();

    requestAnimationFrame(loop);
  }

  loop();
})();
</script>
</body>
</html>
```

The script draws a sinusoidal cave, scrolls it leftward while an autonomous ship steers toward the upcoming gap center using a proportional controller, and updates a distance counter.
